import SpiderCore

/// Names and locations of the "Classic" card face images (Sources/SpiderSolitaire/Resources/Cards,
/// generated by scripts/cards/build_classic_cards.py). Pure string logic so it is testable on Linux;
/// the app turns the paths into NSImages.
public enum ClassicCardArt {
    /// SwiftPM names an executable target's resource bundle `<Package>_<Target>`.
    public static let resourceBundleName: String = "SpiderSolitaire_SpiderSolitaire"
    /// `.copy("Resources/Cards")` keeps the folder name inside the bundle.
    public static let subdirectory: String = "Cards"
    public static let fileExtension: String = "png"
    /// Pixel size of every image. The art keeps the source deck's own 2:3 proportions (360 × 540
    /// SVGs); CardView fits it into the 71:96 card with one uniform scale (white margins left and
    /// right), so nothing is stretched. 360 px tall covers 2x the largest card (162 pt).
    public static let pixelWidth: Int = 240
    public static let pixelHeight: Int = 360
    /// Width / height of the source art.
    public static let artAspect: Double = 360.0 / 540.0

    /// "spades_king", "hearts_10", "clubs_ace"... Must match `asset_name` in the build script.
    public static func assetName(rank: Rank, suit: Suit) -> String {
        "\(suitWord(suit))_\(rankWord(rank))"
    }

    public static func assetName(for card: Card) -> String {
        assetName(rank: card.rank, suit: card.suit)
    }

    /// All 52 names, spades then hearts, diamonds, clubs, each ace to king.
    public static var allAssetNames: [String] {
        Suit.allCases.flatMap { (suit: Suit) -> [String] in
            Rank.allCases.map { (rank: Rank) -> String in assetName(rank: rank, suit: suit) }
        }
    }

    public static func fileName(rank: Rank, suit: Suit) -> String {
        assetName(rank: rank, suit: suit) + "." + fileExtension
    }

    static func suitWord(_ suit: Suit) -> String {
        switch suit {
        case .spades: return "spades"
        case .hearts: return "hearts"
        case .diamonds: return "diamonds"
        case .clubs: return "clubs"
        }
    }

    static func rankWord(_ rank: Rank) -> String {
        switch rank {
        case .ace: return "ace"
        case .jack: return "jack"
        case .queen: return "queen"
        case .king: return "king"
        default: return String(rank.rawValue)
        }
    }

    /// Where the resource bundle can live, most specific first:
    /// 1. `X.app/Contents/Resources/<bundle>` — where scripts/package.sh puts it (the only place
    ///    a signed .app may hold it).
    /// 2. `X.app/<bundle>` / next to the executable — where SwiftPM's generated `Bundle.module`
    ///    looks, and where `swift run` / Xcode builds put it (`.build/<config>/`).
    /// SwiftPM uses `.bundle` on Apple platforms and `.resources` elsewhere; both are listed.
    public static func bundleCandidates(resourcePath: String?, mainBundlePath: String, executablePath: String?) -> [String] {
        var directories: [String] = []
        if let resourcePath { directories.append(resourcePath) }
        directories.append(mainBundlePath)
        if let executablePath { directories.append(parentDirectory(of: executablePath)) }
        var result: [String] = []
        for directory in directories {
            for suffix in [".bundle", ".resources"] {
                let path: String = join(directory, resourceBundleName + suffix)
                if !result.contains(path) { result.append(path) }
            }
        }
        return result
    }

    /// Paths an image may have inside one bundle: flat (what `swift build` produces) or the
    /// standard macOS layout (`Contents/Resources`, what package.sh produces).
    public static func imagePathCandidates(bundlePath: String, assetName: String) -> [String] {
        let file: String = assetName + "." + fileExtension
        return [
            join(join(join(bundlePath, "Contents/Resources"), subdirectory), file),
            join(join(bundlePath, subdirectory), file),
        ]
    }

    static func join(_ directory: String, _ component: String) -> String {
        directory.hasSuffix("/") ? directory + component : directory + "/" + component
    }

    static func parentDirectory(of path: String) -> String {
        var trimmed: Substring = Substring(path)
        while trimmed.count > 1 && trimmed.hasSuffix("/") { trimmed = trimmed.dropLast() }
        guard let slash: Substring.Index = trimmed.lastIndex(of: "/") else { return "." }
        if slash == trimmed.startIndex { return "/" }
        return String(trimmed[trimmed.startIndex..<slash])
    }
}
